	private String findBaseRate(String npcName, String itemName)
	{
		Map<String, String> fromPrimaryNpc = primaryDrops.get(npcName);
		if (fromPrimaryNpc != null)
		{
			String rarity = fromPrimaryNpc.get(itemName);
			if (rarity != null)
			{
				return rarity;
			}
		}

		Map<String, String> fromPrimaryItem = primaryDrops.get(itemName);
		if (fromPrimaryItem != null)
		{
			String rarity = fromPrimaryItem.get(npcName);
			if (rarity != null)
			{
				return rarity;
			}
		}

		Map<String, String> fromInvertedNpc = invertedDrops.get(npcName);
		if (fromInvertedNpc != null)
		{
			return fromInvertedNpc.get(itemName);
		}

		return null;
	}

	private Map<String, Map<String, String>> invertDropMap(Map<String, Map<String, String>> input)
	{
		Map<String, Map<String, String>> inverted = new HashMap<>();
		if (input == null || input.isEmpty())
		{
			return inverted;
		}

		for (Map.Entry<String, Map<String, String>> outer : input.entrySet())
		{
			String outerKey = outer.getKey();
			Map<String, String> inner = outer.getValue();
			if (inner == null || inner.isEmpty())
			{
				continue;
			}

			for (Map.Entry<String, String> innerEntry : inner.entrySet())
			{
				inverted
					.computeIfAbsent(innerEntry.getKey(), k -> new HashMap<>())
					.put(outerKey, innerEntry.getValue());
			}
		}

		return inverted;
	}

	private Chance parseChance(String rarity)
	{
		try
		{
			// Malformed data (e.g. an unevaluated wiki template) must never
			// half-match and produce a wrong rate — reject it outright.
			if (rarity.indexOf('{') >= 0)
			{
				return null;
			}

			Matcher matcher = CHANCE_PATTERN.matcher(rarity);
			if (!matcher.find())
			{
				return null;
			}

			double multiplier = matcher.group(1) != null ? parseRateNumber(matcher.group(1)) : 1.0d;
			double baseNumerator = parseRateNumber(matcher.group(2));
			double denominator = parseRateNumber(matcher.group(3));
			if (denominator <= 0)
			{
				return null;
			}

			return new Chance(multiplier * baseNumerator, denominator);
		}
		catch (Exception e)
		{
			return null;
		}
	}

	private double getEffectiveRate(Chance chance, String rarity)
	{
		if (chance != null && chance.numerator > 0)
		{
			return chance.denominator / chance.numerator;
		}

		try
		{
			if (rarity.indexOf('{') >= 0)
			{
				return 0;
			}

			Matcher matcher = CHANCE_PATTERN.matcher(rarity);
			if (!matcher.find())
			{
				return 0;
			}

			double denominator = parseRateNumber(matcher.group(3));
			return denominator > 0 ? denominator : 0;
		}
		catch (Exception e)
		{
			return 0;
		}
	}

	private double parseRateNumber(String rawNumber)
	{
		if (rawNumber == null)
		{
			throw new NumberFormatException("null");
		}

		String value = rawNumber.trim();
		if (value.isEmpty())
		{
			throw new NumberFormatException("empty");
		}

		int commaIdx = value.lastIndexOf(',');
		int dotIdx = value.lastIndexOf('.');

		if (commaIdx >= 0 && dotIdx >= 0)
		{
			if (commaIdx > dotIdx)
			{
				value = value.replace(".", "").replace(',', '.');
			}
			else
			{
				value = value.replace(",", "");
			}
		}
		else if (commaIdx >= 0)
		{
			if (value.matches("\\d{1,3}(,\\d{3})+"))
			{
				value = value.replace(",", "");
			}
			else if (value.matches("\\d+,\\d{1,2}"))
			{
				value = value.replace(',', '.');
			}
			else
			{
				value = value.replace(",", "");
			}
		}

		return Double.parseDouble(value);
	}

	/**
	 * The single source of truth for what Common, Uncommon, Rare and Ultra-rare mean.
	 * Both the tier colours and the "Minimum rarity to show in chat" filter read the
	 * player's own tier boundaries through here, so the two can never disagree.
	 *
	 * <p>The boundaries are clamped into a strictly increasing order because each one
	 * is edited independently in the config panel. A rate we could not parse comes in
	 * as 0 and lands on Common, which is the tier its colour has always used.
	 *
	 * <p>Takes the config rather than reading the field so the rare-only migration,
	 * which has to run before injection, can classify a threshold with it too.
	 */
	private static DropRateTier classifyTier(DropRateConfig config, double rate)
	{
		int commonTierMax = Math.max(1, config.commonTierThreshold());
		int rareTierMin = Math.max(commonTierMax + 1, config.rareColorThreshold());
		int ultraRareTierMin = Math.max(rareTierMin + 1, config.ultraRareColorThreshold());

		if (rate >= ultraRareTierMin)
		{
			return DropRateTier.ULTRA_RARE;
		}

		if (rate >= rareTierMin)
		{
			return DropRateTier.RARE;
		}

		if (rate > commonTierMax)
		{
			return DropRateTier.UNCOMMON;
		}

		return DropRateTier.COMMON;
	}

	/**
	 * Whether a drop is rare enough to be worth a chat line. The drop keeps whatever
	 * rarity {@link #classifyTier} gives it; this only decides whether that tier is
	 * at or past the one the player asked to be told about. Common is the lowest tier
	 * and the default, so it lets everything through.
	 */
	private boolean passesMinimumRarity(double effectiveRate)
	{
		return classifyTier(config, effectiveRate).compareTo(config.minimumChatRarity()) >= 0;
	}

	private Color getColor(double rate)
	{
		if (config.colorMode() == DropRateColorMode.NEUTRAL_WHITE)
		{
			return WHITE;
		}

		switch (classifyTier(config, rate))
		{
			case ULTRA_RARE:
			{
				Color c = config.ultraRareTierColor();
				return c != null ? c : DEFAULT_PURPLE;
			}
			case RARE:
			{
				Color c = config.rareTierColor();
				return c != null ? c : DEFAULT_RED;
			}
			case UNCOMMON:
			{
				Color c = config.uncommonTierColor();
				return c != null ? c : DEFAULT_ORANGE;
			}
			case COMMON:
			default:
			{
				Color c = config.commonTierColor();
				return c != null ? c : DEFAULT_GREEN;
			}
		}
	}

	/**
	 * The tier colour to use for a chat message, adjusted for the chatbox the player
	 * actually has open. Kept separate from {@link #getColor(double)} because the
	 * Collection Log tooltip draws on RuneLite's own dark tooltip background and must
	 * keep the picked colours untouched.
	 */
	private Color getChatColor(double rate)
	{
		Color color = getColor(rate);
		if (!config.adaptChatboxColors() || isTransparentChatbox())
		{
			return color;
		}

		return darkenForOpaqueChatbox(color);
	}

	private boolean isTransparentChatbox()
	{
		try
		{
			// Same test RuneLite's own ChatMessageManager uses: the transparency
			// setting only takes effect in resizable mode, so fixed mode is always
			// the opaque parchment chatbox no matter what the varbit says.
			return client.isResized() && client.getVarbitValue(VarbitID.CHATBOX_TRANSPARENCY) != 0;
		}
		catch (Exception e)
		{
			// Treat an unreadable varbit as the standard chatbox: darkening a colour
			// on the transparent box is still readable, the reverse is what users
			// complained about.
			log.debug("Unable to read the chatbox transparency varbit", e);
			return false;
		}
	}

	/**
	 * Scales a colour towards black until it is dark enough to read on the standard
	 * chatbox's parchment background, keeping its hue. The default orange (255,140,0)
	 * sits at ~1.2:1 contrast there, which is what players reported as unreadable;
	 * the target luminance puts every tier past 3:1. Colours that are already dark
	 * enough (the default red and purple) come back unchanged.
	 */
	private static Color darkenForOpaqueChatbox(Color color)
	{
		if (relativeLuminance(color) <= OPAQUE_CHATBOX_MAX_LUMINANCE)
		{
			return color;
		}

		// Straight bisection on a single scale factor. Luminance is monotonic in the
		// factor, so ten steps land within 0.1% — cheaper and clearer than inverting
		// the sRGB transfer function per channel.
		double low = 0.0d;
		double high = 1.0d;
		for (int i = 0; i < 10; i++)
		{
			double mid = (low + high) / 2.0d;
			if (relativeLuminance(scale(color, mid)) > OPAQUE_CHATBOX_MAX_LUMINANCE)
			{
				high = mid;
			}
			else
			{
				low = mid;
			}
		}

		return scale(color, low);
	}

	private static Color scale(Color color, double factor)
	{
		return new Color(
			(int) Math.round(color.getRed() * factor),
			(int) Math.round(color.getGreen() * factor),
			(int) Math.round(color.getBlue() * factor)
		);
	}

	/** WCAG relative luminance, used only to compare a colour against the chatbox. */
	private static double relativeLuminance(Color color)
	{
		return 0.2126d * linearize(color.getRed())
			+ 0.7152d * linearize(color.getGreen())
			+ 0.0722d * linearize(color.getBlue());
	}

	private static double linearize(int channel)
	{
		double value = channel / 255.0d;
		return value <= 0.04045d ? value / 12.92d : Math.pow((value + 0.055d) / 1.055d, 2.4d);
	}

	private String colorTag(Color color)
	{
		return String.format("<col=%06x>", color.getRGB() & 0xFFFFFF);
	}

	private void migrateLegacyConfig()
	{
		if (configManager.getConfiguration(CONFIG_GROUP, DISPLAY_MODE_KEY) != null)
		{
			return;
		}

		if (!hasLegacyModeConfig())
		{
			return;
		}

		String legacyRareOnly = configManager.getConfiguration(CONFIG_GROUP, LEGACY_RARE_ONLY_KEY);
		String legacyHideAlways = configManager.getConfiguration(CONFIG_GROUP, LEGACY_HIDE_ALWAYS_KEY);
		String legacyHideUseless = configManager.getConfiguration(CONFIG_GROUP, LEGACY_HIDE_USELESS_KEY);

		DropRateDisplayMode migratedMode;
		if (parseLegacyBoolean(legacyRareOnly, false))
		{
			// The mode this used to become filtered by rarity, not by kind of drop,
			// and the rarity filter now owns that job. Show every drop and let the
			// minimum rarity below do the hiding.
			migratedMode = DropRateDisplayMode.ALL_MATCHES;
			adoptRareOnlyThresholdAsMinimumRarity(configManager, config);
		}
		else if (parseLegacyBoolean(legacyHideAlways, true) || parseLegacyBoolean(legacyHideUseless, false))
		{
			migratedMode = DropRateDisplayMode.CLEANER_FEED;
		}
		else
		{
			migratedMode = DropRateDisplayMode.ALL_MATCHES;
		}

		configManager.setConfiguration(CONFIG_GROUP, DISPLAY_MODE_KEY, migratedMode.name());
		log.info("Migrated legacy DropRate config to display mode {}", migratedMode);
	}

	/**
	 * "Rare drops only" was one of three display modes and is now retired in favour of
	 * "Minimum rarity to show in chat". Someone still on it has a display mode stored
	 * that no longer names a constant — RuneLite would quietly fall back to All drops
	 * and print everything at them — so translate it once instead: keep All drops, and
	 * hand the rarity filter the tier their old threshold already sat in.
	 */
	private void migrateRareOnlyMode(ConfigManager configManager, DropRateConfig config)
	{
		if (!RETIRED_RARE_ONLY_MODE.equals(configManager.getConfiguration(CONFIG_GROUP, DISPLAY_MODE_KEY)))
		{
			return;
		}

		adoptRareOnlyThresholdAsMinimumRarity(configManager, config);
		configManager.setConfiguration(CONFIG_GROUP, DISPLAY_MODE_KEY, DropRateDisplayMode.ALL_MATCHES.name());
		log.info("Migrated the retired Rare drops only display mode to All drops");
	}

	/**
	 * Classifies the retired numeric rare-only threshold with the very same tier
	 * boundaries the colours use, so nobody is handed a boundary invented here. With
	 * the old default of 500 and the default tiers that lands on Uncommon. The
	 * classification rounds down by construction, so the new setting can only ever
	 * show a returning player more than the old one did, never less.
	 */
	private void adoptRareOnlyThresholdAsMinimumRarity(ConfigManager configManager, DropRateConfig config)
	{
		if (configManager.getConfiguration(CONFIG_GROUP, MINIMUM_RARITY_KEY) != null)
		{
			return;
		}

		DropRateTier tier = classifyTier(config, readRetiredRareThreshold(configManager));
		configManager.setConfiguration(CONFIG_GROUP, MINIMUM_RARITY_KEY, tier.name());
		log.info("Migrated the retired rare-only threshold to minimum chat rarity {}", tier);
	}

	private int readRetiredRareThreshold(ConfigManager configManager)
	{
		String stored = configManager.getConfiguration(CONFIG_GROUP, RETIRED_RARE_THRESHOLD_KEY);
		if (stored == null)
		{
			return RETIRED_RARE_THRESHOLD_DEFAULT;
		}

		try
		{
			return Integer.parseInt(stored.trim());
		}
		catch (NumberFormatException e)
		{
			return RETIRED_RARE_THRESHOLD_DEFAULT;
		}
	}

	/** Drops the numeric rare-only threshold once the migration above has read it. */
	private void retireRareOnlyThreshold(ConfigManager configManager)
	{
		if (configManager.getConfiguration(CONFIG_GROUP, RETIRED_RARE_THRESHOLD_KEY) == null)
		{
			return;
		}

		configManager.unsetConfiguration(CONFIG_GROUP, RETIRED_RARE_THRESHOLD_KEY);
		log.debug("Removed the retired rare-only threshold setting");
	}

	/**
	 * The rare-drop notification used to be a plain boolean. It is now a RuneLite
	 * {@link Notification}, so users get the standard tray/sound/flash controls.
	 * Carry the old on/off state over once, so nobody silently loses their setting.
	 */
	private void migrateNotificationConfig()
	{
		if ("1".equals(configManager.getConfiguration(CONFIG_GROUP, NOTIFICATION_MIGRATED_KEY)))
		{
			return;
		}

		String legacyNotify = configManager.getConfiguration(CONFIG_GROUP, LEGACY_NOTIFY_KEY);
		if (legacyNotify != null)
		{
			boolean wasEnabled = Boolean.parseBoolean(legacyNotify);
			configManager.setConfiguration(
				CONFIG_GROUP,
				NOTIFICATION_KEY,
				wasEnabled ? Notification.ON : Notification.OFF
			);
			configManager.unsetConfiguration(CONFIG_GROUP, LEGACY_NOTIFY_KEY);
			log.info("Migrated rare drop notification setting (was enabled: {})", wasEnabled);
		}

		configManager.setConfiguration(CONFIG_GROUP, NOTIFICATION_MIGRATED_KEY, "1");
	}

	private boolean parseLegacyBoolean(String value, boolean fallback)
	{
		return value == null ? fallback : Boolean.parseBoolean(value);
	}

	private DropRateDisplayMode getDisplayMode()
	{
		if (configManager.getConfiguration(CONFIG_GROUP, DISPLAY_MODE_KEY) != null)
		{
			return config.displayMode();
		}

		if (!hasLegacyModeConfig())
		{
			return config.displayMode();
		}

		if (parseLegacyBoolean(configManager.getConfiguration(CONFIG_GROUP, LEGACY_RARE_ONLY_KEY), false))
		{
			// Matches migrateLegacyConfig: the rarity half of that setting is carried
			// by the minimum rarity filter, leaving the display mode unrestricted.
			return DropRateDisplayMode.ALL_MATCHES;
		}

		if (parseLegacyBoolean(configManager.getConfiguration(CONFIG_GROUP, LEGACY_HIDE_ALWAYS_KEY), true)
			|| parseLegacyBoolean(configManager.getConfiguration(CONFIG_GROUP, LEGACY_HIDE_USELESS_KEY), false))
		{
			return DropRateDisplayMode.CLEANER_FEED;
		}

		return config.displayMode();
	}

	private boolean hasLegacyModeConfig()
	{
		return configManager.getConfiguration(CONFIG_GROUP, LEGACY_RARE_ONLY_KEY) != null
			|| configManager.getConfiguration(CONFIG_GROUP, LEGACY_HIDE_ALWAYS_KEY) != null
			|| configManager.getConfiguration(CONFIG_GROUP, LEGACY_HIDE_USELESS_KEY) != null;
	}

	private boolean isGuaranteedDrop(Chance chance)
	{
		return chance != null && chance.numerator >= chance.denominator;
	}

	private boolean isFillerDrop(String itemName)
	{
		String normalized = itemName.toLowerCase();
		if (normalized.equals("bones") || normalized.endsWith(" bones")
			|| normalized.equals("ashes") || normalized.endsWith(" ashes"))
		{
			return true;
		}

		if (fillerItems == null)
		{
			fillerItems = parseIgnoredItems(config.extraClutterItems());
		}

		return fillerItems.contains(normalized);
	}

	private Set<String> parseIgnoredItems(String csv)
	{
		Set<String> ignored = new HashSet<>();
		if (csv == null || csv.trim().isEmpty())
		{
			return ignored;
		}

		for (String token : csv.split(","))
		{
			String cleaned = token.trim().toLowerCase();
			if (!cleaned.isEmpty())
			{
				ignored.add(cleaned);
			}
		}

		return ignored;
	}

	private String cleanName(String name)
	{
		if (name == null)
		{
			return null;
		}

		String cleaned = Text.removeTags(name).trim();
		return cleaned.isEmpty() ? null : cleaned;
	}

	private static boolean isBlank(String value)
	{
		return value == null || value.trim().isEmpty();
	}

